(function(root){
 'use strict';
 const A=root.DCArtifacts,R=root.DCRichText;
 const tierName={starting:'Starting',elite_mystery:'Elite / Mystery',boss:'Boss'};
 const sceneArt=()=>'<div class="artifact-scene-art" aria-hidden="true"><img src="assets/dungeon-master.webp" width="3840" height="2160" alt=""></div>';
 function card(item,selected,{esc,button},choice=true,run=null){
  const body='<span class="artifact-illustration"><img src="assets/'+item.icon+'" width="800" height="800" alt="" aria-hidden="true"></span>'+
   '<span class="artifact-tier">'+tierName[item.tier]+'</span><strong class="artifact-name">'+esc(item.name)+'</strong>';
  const effect='<p class="artifact-effect" id="effect-'+item.id+'" data-stm-richtext>'+R.description(item.id)+'</p>';
  const last=run&&R.latest(run,item.id);
  const result=last?'<div class="artifact-last-result" data-stm-richtext><strong>Last resolved effect · Stage '+(last.stage+1)+' · Room '+(last.depth+1)+(last.turn?' · Turn '+last.turn:'')+'</strong><div class="rt-results">'+last.results.map(x=>R.resultHTML(x,last.label)).join('')+'</div></div>':'';
  return '<article class="artifact-card'+(selected?' selected':'')+(choice?'':' owned-artifact')+'" data-id="'+item.id+'">'+
   (choice?button(body,'select-artifact','artifact-select','data-id="'+item.id+'" aria-pressed="'+selected+'" aria-describedby="effect-'+item.id+'"'):body)+effect+result+'</article>';
 }
 function render(run,selected,helpers){
  const {esc,button}=helpers,offer=run.artifactState.offer,items=A.choices(run),opening=offer.kind==='starting',boss=offer.kind==='boss';
  const valid=items.some(a=>a.id===selected),chosen=items.find(a=>a.id===selected);
  const heading=opening?'Choose your first artifact':boss?'A power for the next dungeon':'Claim a dungeon artifact';
  return '<section class="artifact-encounter" data-artifact-kind="'+offer.kind+'" aria-labelledby="artifact-title">'+
   sceneArt()+
   '<aside class="master-dialogue"><p class="eyebrow">THE DUNGEON MASTER</p><blockquote>“'+(opening?'Every path asks a different price. Choose what you carry.':boss?'One dungeon behind you. Take a greater gift into the next.':'The dungeon has yielded a gift. Make it part of your strategy.')+'”</blockquote>'+button('‹ Main Menu','home','text-btn')+'</aside>'+
   '<div class="artifact-choice-panel"><p class="eyebrow">'+(opening?'A GIFT BEFORE THE DESCENT':boss?'SIGIL KEEP CLEARED':'YOUR JOURNEY CONTINUES')+'</p><h1 id="artifact-title" tabindex="-1">'+heading+'</h1>'+
   '<p class="artifact-intro">Choose one, then answer the Master’s question to claim it. Select a colored term to learn its meaning.</p><div class="artifact-choices" role="group" aria-label="Artifact choices">'+items.map(item=>card(item,item.id===selected,helpers)).join('')+'</div>'+
   '<div class="artifact-offer-comparison" data-artifact-preview="'+(chosen?.id||'')+'"></div><p class="artifact-selection" role="status">'+(chosen?esc(chosen.name)+' selected.':'Select a gift to continue.')+'</p><div class="artifact-choice-actions">'+button(boss?'Claim & Enter Deck Tower':opening?'Claim & Choose Your Path':'Claim Artifact','claim-artifact','btn primary',valid?'':'disabled')+
   (!opening&&!boss?button('Leave Without It','skip-artifact','text-btn'):'')+'</div><p class="artifact-save-note">Your choices are saved. Returning to the menu keeps the same offers.</p></div></section>';
 }
 function topicIcon(code){const file=root.DCIconAssets?.topics[code];return file?'<img class="topic-icon" src="assets/'+file+'" width="32" height="32" alt="" aria-hidden="true">':'';}
 function education(run,{esc,button}){
  const Q=root.DCEducation,L=root.DCQuestionLanguage,H=root.STMMechanicsHost,p=Q.pending(run),q=L.question(Q.current(run),L.language()),gift=A.catalog[p.artifactId],word=(en,ms)=>L.language()==='ms'?ms:en;
  const record=q?Q.record(run):null,view=q?root.STMMechanics.session.selectLearningView(q,record):null,closed=!!view?.closed,failed=Q.failed(run);
  const destination=failed?word('Continue without artifact','Teruskan tanpa artifact'):p.kind==='boss'?word('Claim & Enter Deck Tower','Tuntut & Masuk Deck Tower'):p.kind==='starting'?word('Claim & Choose Your Path','Tuntut & Pilih Laluan'):word('Claim & Continue','Tuntut & Teruskan');
  let question='';
  if(q){
   const answers='<div class="education-answers" role="group" aria-labelledby="education-prompt">'+p.choiceOrder.map((id,i)=>{const choice=q.choices.find(c=>c.id===id),wrong=p.attempts.includes(id)&&id!==q.correctChoiceId;return '<div class="education-option">'+button('<span class="education-letter" aria-hidden="true">'+'ABCD'[i]+'</span><span class="sr-only">'+esc(choice.text)+'</span>','education-select','education-answer'+(p.selectedId===id?' selected':'')+(wrong?' incorrect':'')+(closed&&id===q.correctChoiceId?' correct':''),'data-id="'+id+'" aria-label="'+word('Answer ','Jawapan ')+'ABCD'[i]+': '+esc(choice.text)+'" aria-pressed="'+(p.selectedId===id)+'" '+(closed||wrong?'disabled':''))+'<div class="education-answer-copy"><span data-q-rich="choice:'+id+'">'+esc(choice.text)+'</span></div></div>';}).join('')+'</div>';
   const correct=q.choices.find(c=>c.id===q.correctChoiceId),result='<div id="education-feedback" class="education-feedback '+(p.solved?'solved':'')+'" role="status" tabindex="-1"><strong>'+word(p.solved?'Correct. Your artifact is ready to claim.':'The trial is finished. You can continue without the artifact.',p.solved?'Betul. Artifact sedia dituntut.':'Trial telah tamat. Anda boleh teruskan tanpa artifact.')+'</strong><p>'+word('Correct answer: ','Jawapan betul: ')+esc(correct.text)+'</p><p data-q-rich="explanation">'+esc(q.explanation)+'</p>'+(view.feedback?'<p data-q-rich="feedback">'+esc(view.feedback.text)+'</p>':'')+'</div>';
   const helpActions=button(record.hintState.hintUsed?word('Hint Shown','Petunjuk Dibuka'):word('Open Hint','Buka Petunjuk'),'education-hint','btn subtle',closed||record.hintState.hintUsed?'disabled':'')+button(record.hintState.moreHintViewed?word('More Hint Shown','Petunjuk Lanjut Dibuka'):word('Open More Hint','Buka Petunjuk Lanjut'),'education-more-hint','btn subtle',closed||!view.moreHint||record.hintState.moreHintViewed?'disabled':'');
   question='<div class="education-question"><div class="education-meta"><span>'+esc(q.id)+' · '+esc(q.difficulty)+'</span>'+H.coverageHTML(run)+'</div>'+H.workspaceHTML(q,record,view,{esc,reportable:true,kind:'education',key:run.seed+':'+run.started+':'+p.source+':'+q.id,question:'<p id="education-prompt" class="education-prompt" data-q-rich="prompt">'+esc(q.prompt)+'</p>'+H.teachingHTML(q,closed,{esc})+answers,checkAction:button(word('Check Answer','Semak Jawapan'),'education-check','btn primary',p.selectedId?'':'disabled'),helpActions,result,continueAction:button(destination,'education-continue','btn primary'),stepsAction:button(record.stepsViewed?word('Hide Steps','Sembunyikan Langkah'):word('Show Steps','Tunjukkan Langkah'),'education-steps','btn subtle','aria-expanded="'+record.stepsViewed+'"'),basicsAction:button(word('Basics','Asas'),'education-basics','btn subtle'),note:word('Two attempts. Incorrect answers do not cost HP. A correct answer is needed to claim this artifact.','Dua cubaan. Jawapan salah tidak mengurangkan HP. Jawapan betul diperlukan untuk menuntut artifact ini.')})+'</div>';
  }else question='<div class="education-question"><h2>'+word('You have seen all 120 questions.','Anda telah melihat kesemua 120 soalan.')+'</h2><p>'+word('No unused questions remain in this run. Continue to claim your artifact.','Tiada soalan baharu dalam run ini. Teruskan untuk menuntut artifact anda.')+'</p>'+button(destination,'education-continue','btn primary')+'</div>';
  return '<section class="artifact-encounter education-encounter" data-question-id="'+(q?.id||'exhausted')+'" data-topic="'+(q?.topicCode||'')+'" aria-labelledby="education-title">'+sceneArt()+'<aside class="master-dialogue"><p class="eyebrow">THE DUNGEON MASTER</p><blockquote>“Knowledge opens the way. Show me what you know.”</blockquote>'+button('‹ Main Menu','home','text-btn')+'</aside><div class="education-panel" data-question-scroll="'+esc(run.seed+':'+run.started+':'+p.source+':'+(q?.id||'exhausted'))+'" tabindex="0" role="region" aria-labelledby="education-title"><p class="eyebrow topic-label">'+(q?topicIcon(q.topicCode)+word('CHAPTER ','BAB ')+q.chapter+' · '+esc(q.topic):word('ALL QUESTIONS SEEN','SEMUA SOALAN TELAH DILIHAT'))+'</p><h1 id="education-title" tabindex="-1">'+word('The Master’s trial','Trial Dungeon Master')+'</h1><details class="education-gift-summary"><summary><img src="assets/'+gift.icon+'" width="36" height="36" alt=""><span>'+word('Chosen artifact: ','Artifact dipilih: ')+esc(gift.name)+'</span></summary><p data-stm-richtext>'+R.description(gift.id)+'</p></details>'+question+'</div></section>';
 }
 function inventory(run,helpers){
  const items=A.owned(run);
  return '<p>Artifacts work automatically throughout this run. Green terms explain the game; pink terms explain the math. Purple numbers show resolved results.</p><div class="artifact-result-actions">'+helpers.button('View Calculations','calculations','btn small')+'</div><div class="owned-artifacts-grid">'+
   (items.length?items.map(item=>card(item,false,helpers,false,run)).join(''):'<p>Your next Challenge begins with the Dungeon Master. Choose a Starting artifact before entering the map.</p>')+'</div>'+R.glossary();
 }
 root.DCArtifactUI={render,education,inventory};
})(window);
